&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Have the opportunity to wear different hats and to take ownership of user-facing features from inception to release and beyond&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;To be successful in this opportunity, you will have:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Proven extensive experience in at least one of the following languages: Ruby, Golang, C++ or Python&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Javascript/Typescript and React experience is highly valuable&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;PostgreSQL knowledge is highly valuable&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Networking knowledge (TCP/IP, UDP, …) is highly valuable&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Automated Testing experience (TDD, BDD, etc)&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Field experience with Agile Methodologies&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Ability to operate in settings with strong confidentiality and data privacy protocols&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&lt;strong&gt;#LI-Hybrid&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Who we are and what we stand for:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Nozomi Networks is the leader in OT and IoT Cybersecurity. We protect the world&#39;s critical infrastructure, industrial and government organizations from cyber threats by providing exceptional network visibility, threat detection and operational insight. We’re always innovating and we hire the best at what they do to ensure our customers always have access to fast product enhancements, exceptional engineering support and rapid deployment across continents.&amp;nbsp;If you like a challenge, and value integrity and customer success, we invite you to help Nozomi Networks build the future of OT and IoT cybersecurity.&lt;/p&gt;
&lt;p&gt;Diversity, Inclusion and Belonging are part of our core beliefs, at Nozomi Networks. Diversity of thought, background and culture broadens our knowledge of the world and helps us learn, grow, and gain new perspectives. What makes us all different is what makes us powerful.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Global Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;All of our benefits are customized to the country you are based in, naturally we want to get the best out of our Nozomiers, so we provide the best benefits packages, such as:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Health &amp;amp; Wellness&lt;/li&gt;
&lt;li&gt;Financial&lt;/li&gt;
&lt;li&gt;Work-Life Balance&lt;/li&gt;
&lt;li&gt;Unparalleled Flexible Time-Off&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Need to know information&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Successful candidates will be subjected to background verification checks.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Be cautious of unsolicited messages, fake email addresses, requests for money and unclear job descriptions. Report suspicious activity to authorities. Our open job opportunities and descriptions are posted on Nozomi Networks&#39; career page. If in any doubt please apply for opportunities on our careers website &lt;a href=&quot;https://www.nozominetworks.com/company/careers&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt;.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;If you would like to know more about our Privacy Policy, please click &lt;a href=&quot;https://www.nozominetworks.com/legal/job-applicant-privacy-notice&quot;&gt;here&lt;/a&gt;. Any questions about how we process personal information, or if you would like help exercising your privacy rights please contact us using the email provided within the Privacy Policy.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.ch/english-speaking-jobs">English Speaking Jobs in Switzerland</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Intrinsic is an AI robotics group at Google aiming to reimagine the potential of industrial robotics. Our team believes that advances in AI, perception and simulation will redefine what’s possible for industrial robotics in the near future – with software and data at the core.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our mission is to make industrial robotics intelligent, accessible, and usable for millions more businesses, entrepreneurs, and developers. We are a dynamic team of engineers, roboticists, designers, and technologists who are passionate about unlocking the creative and economic potential of industrial robotics.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;Role&lt;/h2&gt;
&lt;p&gt;As a Robotics Software Engineer, you will develop and implement robust algorithms to facilitate complex robotic operations in real-world manufacturing environments. Our team is responsible for both motion planning and grasping, with this role dedicated specifically to advancing our grasping capabilities. To succeed, you will bring a strong foundation in robotics—whether from a background in motion planning, control systems, or manipulation—to write excellent, production-quality code. You will help abstract the inherent complexity of robotic tasks into intuitive, seamless workflows, enabling users to transition from design to execution without needing deep subject matter expertise. Working alongside a diverse team of roboticists and application engineers, you will integrate and validate solutions across various industrial tasks and contribute to the launch of impactful robotics products.&lt;/p&gt;
&lt;h2&gt;How your work moves the mission forward&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Algorithm Development:&lt;/strong&gt; Design, implement, and maintain efficient, production-ready algorithms for robotic grasping.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Problem Solving:&lt;/strong&gt; Collaborate with the team to apply cutting-edge advancements in robotics to practical, real-world industrial problems.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Technical Execution:&lt;/strong&gt; Transform complex partner requirements into highly reliable, functional, and scalable technical outcomes.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;System Reliability:&lt;/strong&gt; Improve our core robotics software framework, ensuring high code quality and contributing to a highly reliable product.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Skills you will need to be successful&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Master’s degree in Robotics, Computer Science, or a related field.&lt;/li&gt;
&lt;li&gt;2+ years of professional experience in robotics (backgrounds in motion planning, control, or grasping/manipulation are all welcome).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Software Engineering:&lt;/strong&gt; Exceptional programming skills in C++ and Python, with a proven track record of writing clean, efficient, and production-quality software.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Robotics Fundamentals:&lt;/strong&gt; Strong foundation in linear algebra, spatial transformations, kinematics, and rigid body dynamics.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Hardware Experience:&lt;/strong&gt; Direct experience testing, deploying, and iterating on physical robot hardware.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Skills that will differentiate your candidacy&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;PhD in Robotics or a related field with a specific focus on motion planning, controls, or grasping.&lt;/li&gt;
&lt;li&gt;Prior exposure to or interest in robotic grasping and manipulation projects.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Full-Stack Robotics:&lt;/strong&gt; Experience developing across the entire robotics stack, ranging from writing kinematics and motion generation to system integration and testing.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;At Intrinsic, we are proud to be an equal opportunity workplace. Employment at Intrinsic is based solely on a person&#39;s merit and qualifications directly related to professional competence. Intrinsic does not discriminate against any employee or applicant because of race, creed, color, religion, gender, sexual orientation, gender identity/expression, national origin, disability, age, genetic information, veteran status, marital status, pregnancy or related condition (including breastfeeding), or any other basis protected by law. We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. It is Intrinsic’s policy to comply with all applicable national, state and local laws pertaining to nondiscrimination and equal opportunity.&lt;/p&gt;
&lt;p&gt;If you have a disability or special need that requires accommodation, please contact us at: -----<p>Find more <a href="https://www.arbeitnow.ch/english-speaking-jobs">English Speaking Jobs in Switzerland</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;div data-ogsc=&quot;black&quot;&gt;&lt;span data-ogsc=&quot;&quot; data-ogsb=&quot;yellow&quot;&gt;&lt;strong data-ogsc=&quot;&quot; data-olk-copy-source=&quot;MessageBody&quot;&gt;About Acadia Pharmaceuticals&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div data-ogsc=&quot;black&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div data-ogsc=&quot;black&quot;&gt;&lt;span data-ogsc=&quot;&quot; data-ogsb=&quot;yellow&quot;&gt;Acadia is committed to turning scientific promise into meaningful innovation that makes the difference for underserved neurological and rare disease communities around the world. Our commercial portfolio includes the first and only FDA-approved treatments for Parkinson’s disease psychosis and Rett syndrome. We are developing the next wave of therapeutic advancements with a robust and diverse pipeline that includes mid- to late-stage programs in Alzheimer’s disease psychosis and Lewy body dementia psychosis, along with earlier-stage programs that address other underserved patient needs. At Acadia, we’re here to be their difference.&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;&lt;u&gt;Position Summary&lt;/u&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Associate Director, Regulatory Affairs Europe is responsible for the implementation and execution of global regulatory development, submission and lifecycle maintenance strategies for assigned products in Europe. Staying abreast of the ever evolving regulatory and therapeutic landscapes, the Associate Director will inform regional and global strategic plans on a continuous basis. Further, the Associate Director will assist in building a European regulatory infrastructure that is fit for purpose in line with Acadia’s product pipeline, patient and caregiver needs and in full compliance with European regulatory requirements and standards.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;u&gt;Primary Responsibilities&lt;/u&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proactively initiate, manage, submit and maintain regulatory activities in support of the development, commercialization and maintenance of assigned products in compliance with reporting requirements.&lt;/li&gt;
&lt;li&gt;Plan, coordinate and manage Pediatric Investigation Plans and Orphan Designations.&lt;/li&gt;
&lt;li&gt;Responsible for the planning, coordination, authoring and finalisation of major regulatory components of Marketing and Extension Applications, Renewals and Variations&lt;/li&gt;
&lt;li&gt;Plan and coordinate heath authority meetings including the preparation and authoring of major components of briefing documentation in close collaboration with cross-functional teams.&lt;/li&gt;
&lt;li&gt;Develop regulatory strategy for assigned products in line with the global regulatory strategy ensuring competitive labeling and approval timelines in Europe (through centralised, decentralised or national procedures).&lt;/li&gt;
&lt;li&gt;Lead the European Regulatory Subteam during major submissions.&lt;/li&gt;
&lt;li&gt;Monitor, evaluate, and interpret applicable regulatory requirements to assure compliance with external and internal standards.&lt;/li&gt;
&lt;li&gt;Support early access/ compassionate use programs in Europe.&lt;/li&gt;
&lt;li&gt;Execute team, group, or project objectives to ensure they align with Regulatory strategy and corporate goals.&lt;/li&gt;
&lt;li&gt;Maintain appropriate communication within the Regulatory Affairs function and other cross-functional departments primarily at the project team level.&lt;/li&gt;
&lt;li&gt;Participates in professional associations, industry, and trade groups to keep current on regulatory developments, applying knowledge to assigned programs.&lt;/li&gt;
&lt;li&gt;Works with growing independence under the direction of supervisor.&lt;/li&gt;
&lt;li&gt;Other duties as assigned.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;u&gt;Education/Experience/Skills&lt;/u&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;B.S. or M.S. with 7 years of relevant drug development experience, including 5 years relevant regulatory affairs experience in the EU. Ph.D., Pharm. D., or M.D. with 5 years relevant drug development including 3 years regulatory affairs experience in the EU.&lt;/p&gt;
&lt;p&gt;Key Skills:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proven track record of successfully leading major submission components (e.g. Module 1 of a MAA) in Europe.&lt;/li&gt;
&lt;li&gt;Effective regulatory project management (preparation, coordination, submission and maintenance of regulatory applications).&lt;/li&gt;
&lt;li&gt;Ability to coordinate deliverables using effective time management across multiple projects in a cross-geographic and cross-functional matrix team environment.&lt;/li&gt;
&lt;li&gt;Ability to think critically, strategically, independently and solve problems, include the ability to innovate.&lt;/li&gt;
&lt;li&gt;Excellent written and verbal communication skills, demonstrative strong presentation skills.&lt;/li&gt;
&lt;li&gt;Strong interpersonal and teamwork skills.&lt;/li&gt;
&lt;li&gt;Strong regulatory/ scientific writing skills.&lt;/li&gt;
&lt;li&gt;Strong interest to stay abreast of scientific and regulatory standards and procedures.&lt;/li&gt;
&lt;li&gt;High level of motivation, drive, and demonstration of Acadia values.&lt;/li&gt;
&lt;li&gt;Must be willing an able to travel both domestically and internationally as needed.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-HYBRID #NC1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What we offer US-based Employees:&lt;/span&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Competitive base, bonus, new hire and ongoing equity packages&lt;/li&gt;
&lt;li&gt;Medical, dental, and vision insurance&lt;/li&gt;
&lt;li&gt;Employer-paid life, disability, business travel and EAP coverage&lt;/li&gt;
&lt;li&gt;401(k) Plan with a fully vested company match 1:1 up to 5%&lt;/li&gt;
&lt;li&gt;Employee Stock Purchase Plan with a 2-year purchase price lock-in&lt;/li&gt;
&lt;li&gt;15+ vacation days&lt;/li&gt;
&lt;li&gt;13 -15 paid holidays, including office closure between December 24th and January 1st&lt;/li&gt;
&lt;li&gt;10 days of paid sick time&lt;/li&gt;
&lt;li&gt;Paid parental leave benefit&lt;/li&gt;
&lt;li&gt;Tuition assistance&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;EEO Statement (US-based Employees): &lt;/strong&gt;Studies have shown that women and people of color are less likely to apply for jobs unless they believe they meet every one of the qualifications in the exact way they are described in job postings. We are committed to building a diverse, equitable, inclusive, and innovative company, and we are looking for the BEST candidate for the job. That candidate may be one who comes from a less traditional background or may meet the qualifications in a different way. We strongly encourage you to apply, especially if the reason you are the best candidate isn’t exactly what we describe here.&lt;/p&gt;
&lt;p&gt;It is the policy of Acadia to provide equal employment opportunities to all employees and employment applicants without regard to considerations of race, including related to hairstyle, color, religion or religious creed, sexual orientation, gender, gender identity, gender expression, gender transition, country of origin, ancestry, citizenship, age, physical or mental disability, genetic information, legally-protected medical condition or information, marital status, domestic partner status, family care status, military caregiver status, veteran or military status (including reserve status, National Guard status, and military service or obligation), status as a victim of domestic violence, sexual assault or stalking, enrollment in a public assistance program, or any basis protected under federal, state or local law.&lt;/p&gt;
&lt;p&gt;As an equal opportunity employer, Acadia is committed to a diverse workforce. If you are a qualified individual with a disability or a disabled veteran, you have the right to request a reasonable accommodation. Furthermore, you may request additional support if you are unable or limited in your ability to use or access Acadia’s career website due to your disability, along with any accommodations throughout the interview process. To request or inquire about your reasonable accommodation, please complete our&amp;nbsp;&lt;a href=&quot;https://app.smartsheet.com/b/form/43db301ada19415fa7ab365633993f33&quot; target=&quot;_blank&quot;&gt;Reasonable Accommodation Request Form&lt;/a&gt;&amp;nbsp;or contact us at&amp;nbsp;&lt;a ----- -----
&lt;p&gt;Please note that reasonable accommodations granted throughout the recruiting process are not guaranteed to be the same accommodations given if hired. A new request will need to be submitted for any ADA accommodations after starting employment.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;California Applicants: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Please see &lt;/span&gt;&lt;/span&gt;&lt;a href=&quot;https://acadia.com/en-us/legal-policies/privacy#18&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Additional Information for California Residents&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt; within our Privacy Policy.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559991&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Canadian Applicants: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;Please &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;see&lt;/span&gt;&lt;/span&gt; &lt;a href=&quot;https://acadia.com/en-gb/legal-policies/privacy#17&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Additional Information for Canadian Residents&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt; with&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt;in&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 4&quot;&gt; our Privacy Policy.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559991&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
