&lt;ul&gt;
&lt;li data-start=&quot;1472&quot; data-end=&quot;1535&quot;&gt;Projekterfahrung in der &lt;strong&gt;technischen Detailentwicklung&lt;/strong&gt;/&lt;strong&gt;LP5&lt;/strong&gt; in Deutschland (mind. 3 Jahre) mit Schwerpunkt technische Detailentwicklung (insb. Gebäudehülle und Rohbau)&lt;/li&gt;
&lt;li data-start=&quot;1472&quot; data-end=&quot;1535&quot;&gt;Kenntnisse der relevanten&amp;nbsp;&lt;strong data-start=&quot;1629&quot; data-end=&quot;1666&quot;&gt;deutschen Bauvorschriften- und Normen&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Erfahrung im &lt;strong data-start=&quot;1684&quot; data-end=&quot;1695&quot;&gt;Holzbau&lt;/strong&gt;&lt;/li&gt;
&lt;li data-start=&quot;1538&quot; data-end=&quot;1600&quot;&gt;Erfahrung im Umgang mit den &lt;strong data-start=&quot;1551&quot; data-end=&quot;1598&quot;&gt;Gebäudeklassen 4 und/oder 5&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong data-start=&quot;1800&quot; data-end=&quot;1845&quot;&gt;Fließende Englischkenntnisse&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong data-start=&quot;1800&quot; data-end=&quot;1845&quot;&gt;Gute Deutschkenntnisse&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Bevorzugte Voraussetzungen&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Erfahrung im &lt;strong data-start=&quot;1551&quot; data-end=&quot;1598&quot;&gt;Wohnungsbau &lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Erfahrung mit&amp;nbsp;&lt;strong data-start=&quot;1714&quot; data-end=&quot;1723&quot;&gt;Revit&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Erfahrung mit&amp;nbsp;&lt;strong data-start=&quot;1742&quot; data-end=&quot;1753&quot;&gt;AutoCAD&lt;/strong&gt;; und Kenntnisse in&amp;nbsp;&lt;strong data-start=&quot;1769&quot; data-end=&quot;1778&quot;&gt;Rhino&lt;/strong&gt; sind von Vorteil&lt;/li&gt;
